parameters.text:
=You are a Brand Compliance Auditor. Evaluate the draft content against the brand rules.

Draft Content:
{{ $('Webhook').item.json.body.text }}

Brand Rules:
{{ JSON.stringify($('Execute a SQL query').all().map(item => item.json)) }}

Return a JSON object with "brand_score" (0-100) and "summary".

parameters.jsCode:
// Safely extract input from previous nodes
const inputItem = $input.first().json;
let rawOutput = inputItem.output || inputItem.text || "";

// If nested under LLM response format
if (typeof rawOutput === 'object') {
    rawOutput = JSON.stringify(rawOutput);
}

let evaluation;
try {
    const cleanedOutput = String(rawOutput).replace(/```json/g, '').replace(/```/g, '').trim();
    evaluation = JSON.parse(cleanedOutput);
} catch (e) {
    evaluation = { 
        tone_score: 65, 
        claim_score: 60, 
        violations: [
            { rule_cited: "Tone", flagged_text: "Hey guys", suggested_fix: "Hello team" },
            { rule_cited: "Claim", flagged_text: "100% risk-free / guaranteed profit", suggested_fix: "Remove absolute financial claims" }
        ] 
    };
}

const tone = Number(evaluation.tone_score) || 65;
const claim = Number(evaluation.claim_score) || 60;
const finalScore = Math.round((tone * 0.5) + (claim * 0.5));

return [{
    json: {
        brand_score: finalScore,
        requires_human_review: finalScore < 85,
        violations_count: evaluation.violations ? evaluation.violations.length : 0,
        violations: evaluation.violations || [],
        summary: finalScore >= 85 
            ? "Content passed brand compliance audit successfully." 
            : "Audit flagged non-compliant claims and informal tone requiring review."
    }
}];
